style.css:
@-moz-document domain("youtube.com") {
html, body {
        background-color: #1a0000 !important;
    }

    ytd-app, ytd-page-manager, ytd-watch-flexy, #page-manager, tp-yt-app-drawer {
        background-color: #2b0000 !important;
    }

    ytd-masthead, ytd-masthead #container, ytd-masthead #background {
        background-color: #3d0000 !important;
    }

    /* Yazılar kırmızı */
    yt-formatted-string, h1, h2, h3, a, span {
        color: #ff4d4d !important;
    }

    /* İKONLARI BİLEĞİNDEN ZORLA BEYAZ YAP */
    yt-icon, tp-yt-iron-icon, svg, path {
        fill: #ffffff !important;
        color: #ffffff !important;
        stroke: none !important;
    }

    /* Ekstra koruma: tüm SVG’lere stil override */
    svg[viewBox], yt-icon path, tp-yt-iron-icon path {
        fill: #ffffff !important;
        color: #ffffff !important;
    }

    /* Butonlar */
    ytd-button-renderer, tp-yt-paper-button, button {
        background-color: #cc0000 !important;
        color: white !important;
        border-radius: 6px !important;
        border: none !important;
    }

    ytd-button-renderer:hover, tp-yt-paper-button:hover, button:hover {
        background-color: #ff1a1a !important;
    }

    ytd-video-primary-info-renderer,
    ytd-video-secondary-info-renderer,
    #comments, #secondary {
        background-color: #220000 !important;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #cc0000 !important;
    }

    ::selection {
        background: #ff0000 !important;
        color: white !important;
    }
}
